import json
p='country_unique.json'
d=json.load(open(p,encoding='utf8'))
L=["https://www.tarom.ro/en/about-your-trip/controlul-vamal","TAROM (Romanian national airline): customs clearance"]
S="Unofficial source, read 22 November 2026: TAROM, the Romanian national airline, page \"Customs clearance\". It is not the customs authority's page, whose site could not be read."
d['cash']['romania']={"h":"What TAROM tells passengers about cash in Romania","p":["TAROM, Romania's national airline, tells passengers entering or leaving Romania to include cash above 10,000 euros, or the equivalent in another currency, in their customs statement. The same list names weapons and explosives, medicines and chemicals, jewels beyond personal needs, and art objects that belong to the state heritage.","That matches the EU rule on our card: declare EUR 10,000 or more when entering or leaving the EU. The airline page is not the customs authority, so confirm the form and the corridor with Romanian customs."],"src":S,"link":L}
d['tobacco']['romania']={"h":"What TAROM tells passengers about tobacco in Romania","p":["TAROM's customs page says passengers should declare cigarettes above two cartons, 200 pieces, when entering or leaving Romania.","The Travel Doc customs page we read earlier gives travellers aged 18 and over from outside the EU 200 cigarettes, 100 cigarillos, 50 cigars or 250 g of smoking tobacco, or a proportional mix. Neither page is the customs authority's, so confirm with Romanian customs."],"src":S+" The Travel Doc page (infopages.traveldoc.aero) is undated and names no publisher.","link":L}
d['alcohol']['romania']={"h":"What TAROM tells passengers about alcohol in Romania","p":["TAROM's customs page says passengers should declare alcoholic beverages above 1 litre when entering or leaving Romania.","The Travel Doc customs page we read earlier allows travellers aged 18 and over from outside the EU 1 litre of drinks above 22% or 2 litres of drinks up to 22%, plus 4 litres of still wine and 16 litres of beer. Neither is the customs authority's page, so confirm with Romanian customs."],"src":S+" The Travel Doc page (infopages.traveldoc.aero) is undated and names no publisher.","link":L}
open(p,'w',encoding='utf8',newline='').write(json.dumps(d,separators=(',',':'),ensure_ascii=False))
